written_at.fn_text:
export async function acceptInviteForExistingUserAction(token: string) {
  const user = await requireUser();
  const invite = await prisma.invite.findUnique({ where: { token }, include: { workspace: true } });
  if (!invite || invite.status !== "PENDING" || invite.expiresAt < new Date()) {
    return;
  }

  await prisma.$transaction(async (tx) => {
    await tx.membership.upsert({
      where: { userId_workspaceId: { userId: user.id, workspaceId: invite.workspaceId } },
      update: {},
      create: { userId: user.id, workspaceId: invite.workspaceId, role: invite.role },
    });
    await tx.invite.update({ where: { id: invite.id }, data: { status: "ACCEPTED", acceptedAt: new Date() } });
  });

  redirect(`/w/${invite.workspace.slug}`);
}

